#!/usr/bin/env python3
"""Generate engines/additive.lisp (Plaits additive_engine.cc, unrolled)."""
import os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
L = []
w = L.append
w("""; ======================================================================
; Additive engine (plaits/dsp/engine/additive_engine.cc), generated by
; tools/gen_additive.py. OUT = 24 integer harmonics (two 12-partial
; HarmonicOscillator banks), AUX = 8 "organ" harmonics (1 2 3 4 6 8 10 12).
; Per-block UpdateAmplitudes (one-pole 0.001 + in-place normalisation) runs on
; bstart; partial amplitudes are interpolated per sample like
; HarmonicOscillator's ParameterInterpolators. Partials use the same
; Chebyshev recursion as the C++ (driven by 2*sin(phase)).
; ======================================================================

; Raw (un-smoothed) gain of partial i for one UpdateAmplitudes call.
(defmacro additive-gain (i center slope bumps)
  (def order (* (abs (- i center)) slope))
  (def g0 (- 1 order))
  (def g1 (+ g0 (abs g0)))
  (def g2 (* g1 g1 (+ 1 (sin (* twopi (+ 0.25 (* order bumps)))))))
  (def g3 (* g2 g2))
  (* g3 g3))

; One amplitude slot: ONE_POLE(a, gain, 0.001) on bstart, before normalisation.
(defmacro additive-pre (h gain bstart)
  (+ (read-history h) (* 0.001 (- gain (read-history h)))))
""")

ORGAN = [0, 1, 2, 3, 5, 7, 9, 11]

w("""
(defmacro plaits-additive (bstart bphase rise high patched note timbre morph harmonics accent)
  (def f0 (pl-note-to-freq note))
  (def centroid timbre)
  (def raw_bumps harmonics)
  (def raw_slope (* (- 1 (* 0.6 raw_bumps)) morph))
  (def slope (+ 0.01 (* 1.99 raw_slope raw_slope raw_slope)))
  (def bumps (* 16 raw_bumps raw_bumps))
  (def margin (/ (- (/ 1 slope) 1) (+ 1 bumps)))""")
for tag, n in (("i", 24), ("o", 8)):
    w(f"  (def center_{tag} (- (* centroid (+ {n - 1} margin)) (* 0.5 margin)))")
# amplitude state
for j in range(24):
    w(f"  (make-history am_i{j})")
for j in ORGAN:
    w(f"  (make-history am_o{j})")
for i in range(24):
    w(f"  (def pi{i} (additive-pre am_i{i} (additive-gain {i} center_i slope bumps) bstart))")
w("  (def sum_i (/ 1 (+ 0.001 " + " ".join(f"pi{i}" for i in range(24)) + ")))")
for i, j in enumerate(ORGAN):
    w(f"  (def po{j} (additive-pre am_o{j} (additive-gain {i} center_o slope bumps) bstart))")
w("  (def sum_o (/ 1 (+ 0.001 " + " ".join(f"po{j}" for j in ORGAN) + ")))")
for i in range(24):
    w(f"  (def ai{i} (write-history am_i{i} (gswitch bstart (* pi{i} sum_i) (read-history am_i{i}))))")
for j in ORGAN:
    w(f"  (def ao{j} (write-history am_o{j} (gswitch bstart (* po{j} sum_o) (read-history am_o{j}))))")
# oscillator
w("""  (def f (min f0 0.5))
  (make-history h_ph)
  (def ph1 (+ (read-history h_ph) (pl-interp f bstart bphase 0)))
  (def ph (write-history h_ph (gswitch (gte ph1 1) (- ph1 1) ph1)))
  (def two_x (* 2 (sin (* twopi ph))))""")
def bank(prefix, amps, first, prev0, cur0):
    """amps: list of (slot index i, amp symbol or None)."""
    w(f"  (def {prefix}p0 {prev0})")
    w(f"  (def {prefix}c0 {cur0})")
    terms = []
    for i in range(12):
        k = first + i
        a = amps[i]
        if a is not None:
            w(f"  (def {prefix}g{i} (pl-interp (* {a} (- 1 (* 2 (min (* f {k}) 0.5)))) bstart bphase 0))")
            terms.append(f"(* {prefix}g{i} {prefix}c{i})")
        if i < 11:
            w(f"  (def {prefix}c{i+1} (- (* two_x {prefix}c{i}) {prefix}p{i}))")
            w(f"  (def {prefix}p{i+1} {prefix}c{i})")
    return "(+ " + " ".join(terms) + ")"
o1 = bank("a", [f"ai{i}" for i in range(12)], 1, "1", "(* two_x 0.5)")
o2 = bank("b", [f"ai{i+12}" for i in range(12)], 13,
          "(sin (* twopi (+ (* ph 12) 0.25)))", "(sin (* twopi (* ph 13)))")
o3 = bank("c", [f"ao{i}" if i in ORGAN else None for i in range(12)], 1, "1", "(* two_x 0.5)")
w(f"  (def out_sum (+ {o1} {o2}))")
w(f"  (tuple out_sum {o3}))")
open(os.path.join(ROOT, "engines", "additive.lisp"), "w").write("\n".join(L) + "\n")
print("wrote engines/additive.lisp")
